'use strict';

/**
* Return a constructor for creating a NaN-aware summation results object.
*
* @module @stdlib/blas/ext/base/nannsum/results/factory
*
* @example
* var resultsFactory = require( '@stdlib/blas/ext/base/nannsum/results/factory' );
*
* var Results = resultsFactory( 'float64' );
*
* var results = new Results();
* // returns <Results>
*
* results.sum = 11.7586;
* results.count = 5;
*
* var str = results.toString();
* // returns <string>
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
